import React,{useCallback,useEffect,useMemo,useState} from 'react';
import Icon from './icons.jsx';
import {get,post,percent,dailyChange,money,symbols,symbolDescriptions,normalise,rangeValues,marketStatusLabel,formatDate} from './api.js';
